select column_name,data_type,is_nullable from information_schema.columns where table_schema='public' and table_name='push_tokens' and column_name in ('installation_id','last_seen_at') order by column_name;
select p.proname as function_name,p.prosecdef as security_definer,p.proconfig as configuration,has_function_privilege('anon',p.oid,'EXECUTE') as anon_can_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') as authenticated_can_execute,has_function_privilege('service_role',p.oid,'EXECUTE') as service_role_can_execute from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('register_push_installation','unregister_push_installation') order by p.proname;
select policyname,roles,cmd from pg_policies where schemaname='public' and tablename='push_tokens' order by policyname;
